'use strict';
const FOUNDATIONS=[['Emotional safety','Room to share feelings, say no, and ask for space without fear.'],['Consideration','Your feelings, needs, and time matter in my decisions.'],['Consistency','Dependable care. Actions that match our words.'],['Repair','Listen, take responsibility, and follow through after hurt.']];
let sundayPreview=false;
function weekKey(){const d=new Date(state.date+'T12:00:00');return shiftDay(state.date,-d.getDay());}
function reflectionRecord(){state.reflections??={};return state.reflections[weekKey()]??={loved:['','',''],better:['','',''],strong:'',care:'',submitted:false,partnerDone:false,revealed:false};}
function sundayCard(){if(!sundayPreview&&new Date(state.date+'T12:00:00').getDay()!==0)return '';const r=reflectionRecord();return `<section class="weekly-card"><span class="eyebrow">${sundayPreview?'SUNDAY PREVIEW':'OUR SUNDAY RITUAL'} · 5 MIN</span><h2>A little look back.</h2><p>What made you feel loved? What could feel better next week?</p><button class="primary" data-weekly="open">${r.revealed?'Read our reflection':r.submitted?'View our reflection':'Reflect on our week'} ${icon('arrow')}</button></section>`;}
function weeklySection(){const r=reflectionRecord();return `<section class="weekly-section"><div class="history-head"><h2>This Week</h2><span>No pressure. Just us.</span></div><button class="tool-tile" data-weekly="open"><span class="extra-icon">${icon('heart')}</span><span><strong>Our Sunday reflection</strong><span>${r.revealed?'Saved together in Memories':r.submitted?'Your answers are saved · waiting for your partner':'Two questions, a little appreciation, a fresh intention.'}</span></span>${icon('chevron')}</button>${state.pausePlan?`<button class="tool-tile" data-weekly="pause"><span class="extra-icon">${icon('clock')}</span><span><strong>Our reconnect plan</strong><span>${esc(state.pausePlan.when)} · ${state.pausePlan.done?'Reconnected':'Private draft'}</span></span>${icon('chevron')}</button>`:''}</section>`;}
function foundationsCard(){return `<section class="foundations-card"><span class="eyebrow">OUR FOUR FOUNDATIONS</span><h2>The everyday essentials.</h2><p>Things we practice, without scoring each other.</p>${FOUNDATIONS.map(([name,copy],i)=>`<div class="foundation-row"><span>0${i+1}</span><div><h3>${name}</h3><p>${copy}</p></div></div>`).join('')}</section>`;}
function reflectionFields(key,title,values){return `<fieldset class="reflection-fields"><legend>${title}</legend>${[0,1,2].map(i=>`<label for="${key}-${i}">${i+1}<input id="${key}-${i}" data-reflection="${key}" data-index="${i}" maxlength="240" value="${esc(values[i]||'')}" placeholder="One specific moment…"></label>`).join('')}</fieldset>`;}
function foundationSelect(id,label,value){return `<label for="${id}">${label}</label><select id="${id}"><option value="">Choose if you’d like</option>${FOUNDATIONS.map(([name])=>`<option ${value===name?'selected':''}>${name}</option>`).join('')}</select>`;}
function openReflection(key){const archived=typeof key==='string',r=archived?state.reflections?.[key]:reflectionRecord();if(!r)return;modalName='weekly';let body='';
 if(r.revealed){body=`<span class="success-pill">${icon('check')} OUR WEEK, TOGETHER</span><p>Read with curiosity. Talk through one thing at a time.</p>${reflectionAnswers(state.me,r)}${reflectionAnswers(state.partner,r.partner)}<button class="secondary" data-weekly="intention">Choose one small intention for next week ${icon('arrow')}</button>`;}
 else if(r.submitted){body=`<div class="waiting-art">${icon('lock')}</div><h3>Your reflection is saved.</h3><p>${r.partnerDone?'You both finished. Open your reflections when you’re ready.':'Your partner’s answers stay hidden until you both finish.'}</p><div class="inset-note">Demo only. Hidden answers are a visual simulation.</div><button class="primary" data-weekly="${r.partnerDone?'reveal':'partner'}">${r.partnerDone?'Reveal our reflections':'Simulate '+esc(state.partner)+' finishing'}</button>`;}
 else{body=`<p>Answer from your own experience. Be specific and kind. One example is enough; three is welcome.</p><p class="inset-note">You’re answering about ${esc(state.partner)}. Your draft stays private in this browser.</p><form id="reflection-form">${reflectionFields('loved','What are three things I did this week that made you feel loved?',r.loved)}${reflectionFields('better','What are three things I could have done differently to help you feel more loved or supported?',r.better)}<p class="reflection-context">The “I” in each question means ${esc(state.partner)}. Share what their actions meant to you, and what would help next time.</p>${foundationSelect('foundation-strong','Which foundation felt strongest?',r.strong)}${foundationSelect('foundation-care','Which could use a little more care?',r.care)}<p class="error-text" id="reflection-error" role="alert"></p><button class="primary" type="submit">Save my reflection ${icon('lock')}</button><button type="button" class="extra-text-button full" data-action="close">Later · keep my private draft</button></form>`;}
 modal('Our Sunday reflection.',body);
}
function reflectionAnswers(name,r){if(!r)return '';return `<div class="response"><span class="response-label">${esc(name)}</span><h3>What helped me feel loved</h3><ul>${r.loved.filter(Boolean).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>What would help next time</h3><ul>${r.better.filter(Boolean).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${r.strong?`<p><strong>Felt strong:</strong> ${esc(r.strong)}</p>`:''}${r.care?`<p><strong>More care:</strong> ${esc(r.care)}</p>`:''}</div>`;}
function reflectionMemories(){const entries=Object.entries(state.reflections||{}).filter(([,r])=>r.revealed).sort((a,b)=>b[0].localeCompare(a[0]));return entries.length?`<section class="weekly-section"><h2>Our Sunday reflections</h2>${entries.map(([key])=>`<button class="tool-tile" data-weekly="memory" data-key="${key}"><span class="extra-icon">${icon('heart')}</span><span><strong>A little look back</strong><span>Week of ${prettyDate(key,{month:'short',day:'numeric'})} · Both reflected</span></span>${icon('chevron')}</button>`).join('')}</section>`:'';}
function openPause(){const p=state.pausePlan||{};modalName='pause';modal('Pause & reconnect.',`<p>Sometimes you need space before you can find your words. Give that space a gentle return point.</p><form id="pause-form"><label for="pause-need">What would help right now?</label><select id="pause-need">${['A little quiet to find my words','A slower, softer conversation','Time to settle before we continue'].map(x=>`<option ${p.need===x?'selected':''}>${x}</option>`).join('')}</select><label for="pause-when">When would you like to talk again?</label><input id="pause-when" maxlength="80" required placeholder="Tonight at 7, or in 30 minutes" value="${esc(p.when||'')}"><label for="pause-note">What would you like them to know? <span class="muted-inline">Optional</span></label><textarea id="pause-note" maxlength="300" placeholder="I care about us. I’m having trouble finding my words.">${esc(p.note||'')}</textarea><p class="inset-note">Private draft only. Nothing is sent and no reminder is scheduled. A return time is a request you can agree on together.</p><button class="primary" type="submit">Preview my words ${icon('arrow')}</button></form>${p.when?`<button class="extra-text-button full" data-weekly="reconnected">${p.done?'We’ve marked this as reconnected':'We’ve reconnected'}</button>`:''}`);}
function pausePreview(){const p=state.pausePlan;modalName='pause-preview';modal('A little room to breathe.',`<span class="eyebrow">YOUR PRIVATE DRAFT</span><div class="pause-quote"><p>“I need ${esc(p.need.toLowerCase())}. ${esc(p.note)} Could we come back to this ${esc(p.when)}?”</p></div><p>You can use these words in person or in your own message.</p><button class="primary" data-action="close">Keep this in This Week ${icon('check')}</button><button class="secondary" data-weekly="pause">Edit my words</button>`);}
document.addEventListener('input',e=>{if(e.target.dataset.reflection){const r=reflectionRecord();if(r.submitted)return;r[e.target.dataset.reflection][Number(e.target.dataset.index)]=e.target.value.slice(0,240);persist();}});
document.addEventListener('change',e=>{if(['foundation-strong','foundation-care'].includes(e.target.id)){const r=reflectionRecord();if(!r.submitted){r[e.target.id==='foundation-strong'?'strong':'care']=e.target.value;persist();}}});
document.addEventListener('submit',e=>{if(e.target.id==='reflection-form'){e.preventDefault();const r=reflectionRecord();if(!r.loved.some(x=>x.trim())||!r.better.some(x=>x.trim())){$('#reflection-error').textContent='Add at least one thought for each question, or come back later.';return;}r.submitted=true;persist();render();openReflection();}if(e.target.id==='pause-form'){e.preventDefault();const when=$('#pause-when').value.trim();if(!when)return;state.pausePlan={need:$('#pause-need').value,when:when.slice(0,80),note:$('#pause-note').value.trim().slice(0,300),done:false};persist();render();pausePreview();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-weekly]');if(!b)return;const a=b.dataset.weekly;if(a==='open')openReflection();if(a==='preview'){sundayPreview=!sundayPreview;closeModal();navigate('today');}if(a==='memory')openReflection(b.dataset.key);if(a==='partner'){const r=reflectionRecord();if(!r.submitted)return;r.partnerDone=true;persist();openReflection();}if(a==='reveal'){const r=reflectionRecord();if(!r.submitted||!r.partnerDone)return;r.partner={loved:['You checked in before my busy day.','You listened without rushing me.','You made time for our call.'],better:['Ask before making plans for us.','Let me know if you’ll be late.','Choose a calm time for hard conversations.'],strong:'Consideration',care:'Consistency'};r.revealed=true;persist();render();openReflection();}if(a==='intention')taskForm(null,{title:'Practice one small change from our reflection',owner:'us',note:'Choose one specific, doable action together.'});if(a==='pause')openPause();if(a==='reconnected'&&state.pausePlan){state.pausePlan.done=true;persist();closeModal();render();toast('A little return to each other.');}});
